# Browse local PNG/GIF files using Tk PhotoImage, without Pillow.
import os
import struct
from pathlib import Path
import tkinter as tk


def slide_scan(folder):
    # Scan at most 5000 entries and keep at most 500 regular image files.
    files = []
    with os.scandir(folder) as entries:
        for count, entry in enumerate(entries):
            if count >= 5000:
                break
            if entry.is_file(follow_symlinks=False) and Path(entry.name).suffix.lower() in (".png", ".gif"):
                files.append(Path(entry.path))
                if len(files) >= 500:
                    break
    return sorted(files, key=lambda path: (path.name.casefold(), path.name))


def slide_dimensions(path):
    # Reject oversized images before asking Tk to decode them.
    if path.stat().st_size > 2 * 1024 * 1024:
        raise ValueError("Image exceeds 2 MiB")
    with path.open("rb") as stream:
        header = stream.read(24)
    if header.startswith(b"\x89PNG\r\n\x1a\n") and len(header) >= 24:
        width, height = struct.unpack(">II", header[16:24])
    elif header[:6] in (b"GIF87a", b"GIF89a") and len(header) >= 10:
        width, height = struct.unpack("<HH", header[6:10])
    else:
        raise ValueError("Not a supported PNG/GIF image")
    if not 0 < width <= 4096 or not 0 < height <= 4096 or width * height > 8000000:
        raise ValueError("Image dimensions exceed the preview limit")
    return width, height


def slide_show(app):
    app.slide_photo = None
    app.ImageLabel.configure(image="", text="No image")
    if not app.slide_files:
        return
    path = app.slide_files[app.slide_index]
    try:
        width, height = slide_dimensions(path)
        image = tk.PhotoImage(master=app.Form1, file=str(path))
        limit_w = max(1, app.ImageLabel.winfo_width() - 10)
        limit_h = max(1, app.ImageLabel.winfo_height() - 10)
        factor = max(1, (width + limit_w - 1) // limit_w, (height + limit_h - 1) // limit_h)
        app.slide_photo = image.subsample(factor)
        app.ImageLabel.configure(image=app.slide_photo, text="")
        app.StatusLabel.configure(text=f"{app.slide_index + 1} / {len(app.slide_files)} | {path.name}")
    except (OSError, ValueError, tk.TclError) as error:
        app.ImageLabel.configure(text="Cannot display this image")
        app.StatusLabel.configure(text=path.name + ": " + str(error))


def slide_pause(app):
    # A generation counter also invalidates callbacks already queued before pause.
    app.slide_generation += 1
    app.slide_playing = False
    if app.slide_job is not None:
        try:
            app.root.after_cancel(app.slide_job)
        except tk.TclError:
            pass
    app.slide_job = None
    app.PlayButton.configure(text="Play")


def slide_open(app):
    folder = filedialog.askdirectory(parent=app.Form1)
    if not folder:
        return
    try:
        files = slide_scan(folder)
        if not files:
            raise ValueError("No PNG/GIF files found within the scan limit")
    except (OSError, ValueError) as error:
        messagebox.showinfo("Open folder", str(error), parent=app.Form1)
        return
    slide_pause(app)
    app.slide_files = files
    app.slide_index = 0
    slide_show(app)


def slide_step(app, step):
    # Manual navigation pauses the automatic slideshow.
    slide_pause(app)
    if app.slide_files:
        app.slide_index = (app.slide_index + step) % len(app.slide_files)
        slide_show(app)


def slide_tick(app, generation):
    if generation != app.slide_generation or not app.slide_playing:
        return
    app.slide_job = None
    app.slide_index = (app.slide_index + 1) % len(app.slide_files)
    slide_show(app)
    interval = max(1, min(10, int(app.IntervalScale.get())))
    app.slide_job = app.root.after(interval * 1000, lambda: slide_tick(app, generation))


def slide_toggle(app):
    if app.slide_playing:
        slide_pause(app)
    elif app.slide_files:
        slide_pause(app)
        app.slide_playing = True
        app.PlayButton.configure(text="Pause")
        generation = app.slide_generation
        interval = max(1, min(10, int(app.IntervalScale.get())))
        app.slide_job = app.root.after(interval * 1000, lambda: slide_tick(app, generation))


def slide_close(app):
    slide_pause(app)
    app.root.destroy()
